      {step === 1 && renderStep1()}
      {step === 2 && renderStep2()}
      {step === 3 && renderStep3()}
      {step === 4 && renderResults()}

      {step < 4 && renderGuide()}
    </div>
  );
};

export default FunnelWizard;

import React, { useState, useEffect } from 'react';
import { generateQuickCopy, analyzeCompetitorImage } from '../services/gemini';
import { Zap, Image as ImageIcon, Copy, Loader2, UploadCloud, Mail, FileText, Save, Lightbulb, CheckCircle2, MessageCircle, Facebook, Video, AlertTriangle, Sparkles, RefreshCw } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { FunnelProject } from '../types';
import VoiceInput from './VoiceInput';
import { Tooltip } from './Tooltip';

interface QuickToolsProps {
  initialTopic?: string;
  initialType?: 'headline' | 'tweet' | 'email_subject' | 'ad_copy' | 'landing_page' | 'lead_magnet' | 'lead_magnet_ideas' | 'email_sequence' | 'whatsapp_template' | 'facebook_post' | 'pov_video_script';
  onAutoSave: (project: FunnelProject) => void;
}

const TEMPLATES = [
  { id: '', label: 'General / No Template' },
  { id: 'Limited-Time Offer', label: 'Limited-Time Offer' },
  { id: 'New Product Launch', label: 'New Product Launch' },
  { id: 'Flash Sale', label: 'Flash Sale (Urgency)' },
  { id: 'Holiday Special', label: 'Holiday Special' },
  { id: 'Problem-Solution', label: 'Problem-Agitate-Solve' },
  { id: 'Storytelling', label: 'Storytelling / Testimonial' },
];

const QuickTools: React.FC<QuickToolsProps> = ({ initialTopic = '', initialType = 'headline', onAutoSave }) => {
  const [activeTab, setActiveTab] = useState<'copy' | 'analyze'>('copy');
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [hasSavedManually, setHasSavedManually] = useState(false);

  // Copy Gen State
  const [topic, setTopic] = useState(initialTopic);
  const [copyType, setCopyType] = useState<'headline' | 'tweet' | 'email_subject' | 'ad_copy' | 'landing_page' | 'lead_magnet' | 'lead_magnet_ideas' | 'email_sequence' | 'whatsapp_template' | 'facebook_post' | 'pov_video_script'>(initialType);
  const [selectedTemplate, setSelectedTemplate] = useState('');

  // Image Analysis State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');

  // Update state if props change (re-navigation)
  useEffect(() => {
    if (initialTopic) setTopic(initialTopic);
    if (initialType) setCopyType(initialType);
  }, [initialTopic, initialType]);

  // Simulated Progress Bar for Analysis
  useEffect(() => {
    let interval: any;
    if (loading && activeTab === 'analyze') {
        setAnalysisProgress(0);
        interval = setInterval(() => {
            setAnalysisProgress(prev => {
                // Fast start, slow end, max 95% until complete
                if (prev >= 95) return prev;
                const increment = prev < 50 ? 5 : prev < 80 ? 2 : 0.5;
                return prev + Math.random() * increment;
            });
        }, 200);
    } else if (!loading && result) {
        setAnalysisProgress(100);
    }
    return () => clearInterval(interval);
  }, [loading, activeTab, result]);


  // Auto-Save Effect when result changes
  useEffect(() => {
      if (!result) return;

      // PREVIEW MODE: Skip auto-save for specific long-form content types
      // This allows the user to review before saving to their project list
      if (activeTab === 'copy' && (copyType === 'email_sequence' || copyType === 'whatsapp_template')) {
          return;
      }

      let type: FunnelProject['type'] = 'COPY';
      if (activeTab === 'analyze') type = 'ANALYSIS';

      const project: FunnelProject = {
          id: Date.now().toString(),
          name: activeTab === 'copy' ? `${copyType.replace(/_/g, ' ')}: ${topic.substring(0, 15)}...` : 'Competitor Analysis',
          type: type,
          content: result,
          niche: activeTab === 'copy' ? topic : 'Image Analysis',
          productName: activeTab === 'copy' ? topic : 'Competitor Image',
          targetAudience: 'General',
          createdAt: Date.now()
      };

      onAutoSave(project);
  }, [result]); // Only runs when result is updated

  const handleVoiceInput = (text: string) => {
    setTopic(prev => prev ? `${prev} ${text}` : text);
  };

  const extractErrorMessage = (e: any): string => {
      if (e instanceof Error) {
          const msg = e.message.toLowerCase();
          if (msg.includes('429')) return "Quota exceeded. Please wait a moment and try again.";
          if (msg.includes('400')) return "Invalid request. Please check your inputs.";
          if (msg.includes('403')) return "Access denied. Please check your API key.";
          if (msg.includes('503')) return "AI service is temporarily unavailable. Please try again later.";
          if (msg.includes('fetch failed')) return "Network error. Please check your internet connection.";
          return e.message;
      }
      return "An unexpected error occurred. Please try again.";
  };

  const handleCopyGen = async () => {
    if (!topic) return;
    setLoading(true);
    setResult(null);
    setError(null);
    setHasSavedManually(false);
    try {
      const text = await generateQuickCopy(topic, copyType, selectedTemplate);
      setResult(text);
    } catch (e) {
      console.error("Copy generation error:", e);
      setError(extractErrorMessage(e));
    } finally {
      setLoading(false);
    }
  };

  const handleManualSave = () => {
    if (!result) return;

    let type: FunnelProject['type'] = 'COPY';
    if (copyType === 'whatsapp_template') type = 'CAMPAIGN_WA';
    if (copyType === 'email_sequence') type = 'CAMPAIGN_EMAIL';

    const project: FunnelProject = {
        id: Date.now().toString(),
        name: `${copyType.replace(/_/g, ' ')}: ${topic.substring(0, 15)}...`,
        type: type,
        content: result,
        niche: topic,
        productName: topic,
        targetAudience: 'General',
        createdAt: Date.now()
    };

    onAutoSave(project);
    setHasSavedManually(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate File Size (Max 4MB)
      if (file.size > 4 * 1024 * 1024) {
          setError("Image is too large. Please upload an image under 4MB to ensure fast analysis.");
          return;
      }
      // Validate File Type
      if (!file.type.startsWith('image/')) {
          setError("Invalid file type. Please upload a valid image (JPEG, PNG, WebP).");
          return;
      }

      setUploading(true);
      setError(null);
      setResult(null);

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setSelectedImage(base64String);
        setMimeType(file.type);
        setResult(null); 
        setHasSavedManually(false);
        setUploading(false);
      };
      reader.onerror = () => {
          setError("Failed to read image file. Please try again.");
          setUploading(false);
      }
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!selectedImage) return;
    setLoading(true);
    setResult(null);
    setError(null);
    setHasSavedManually(false);
    try {
      const text = await analyzeCompetitorImage(selectedImage, mimeType);
      setResult(text);
    } catch (e) {
      console.error("Analysis error:", e);
      setError(extractErrorMessage(e));
    } finally {
      setLoading(false);
    }
  };

  const isPreviewMode = activeTab === 'copy' && (copyType === 'email_sequence' || copyType === 'whatsapp_template');

  return (
    <div className="p-4 h-full flex flex-col">
      <h2 className="text-2xl font-bold text-gray-900 dark:text-gray-100 mb-4">Quick Tools</h2>

      {/* Tabs */}
      <div className="flex bg-gray-100 dark:bg-gray-700 p-1 rounded-xl mb-6">
        <button
          onClick={() => { setActiveTab('copy'); setResult(null); setError(null); setHasSavedManually(false); }}
          className={`flex-1 flex items-center justify-center gap-2 py-2 text-sm font-medium rounded-lg transition-all ${activeTab === 'copy' ? 'bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-300 shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
        >
          <Zap size={16} /> Generator
        </button>
        <button
          onClick={() => { setActiveTab('analyze'); setResult(null); setError(null); setHasSavedManually(false); }}
          className={`flex-1 flex items-center justify-center gap-2 py-2 text-sm font-medium rounded-lg transition-all ${activeTab === 'analyze' ? 'bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-300 shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
        >
          <ImageIcon size={16} /> Vision
        </button>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar pb-20">
        {activeTab === 'copy' ? (
          <div className="space-y-4 animate-in fade-in">
             <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 text-yellow-800 dark:text-yellow-200 px-3 py-2 rounded-lg text-xs flex items-center gap-2">
                <Zap size={12} className="fill-yellow-600 text-yellow-600 dark:text-yellow-400" />
                Powered by Gemini Flash Lite for speed.
             </div>

            <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700 dark:text-gray-300 flex items-center">
                    What do you need?
                    <Tooltip content="Select the type of content you want the AI to generate for you." />
                </label>
                <div className="grid grid-cols-2 gap-2">
                    {[
                        { id: 'headline', label: 'Headline', icon: null },
                        { id: 'tweet', label: 'Tweet', icon: null },
                        { id: 'email_subject', label: 'Subject Lines', icon: null },
                        { id: 'email_sequence', label: 'Email Sequence', icon: <Mail size={12} /> },
                        { id: 'ad_copy', label: 'Ad Copy', icon: null },
                        { id: 'landing_page', label: 'Landing Page', icon: null },
                        { id: 'lead_magnet', label: 'Lead Magnet Text', icon: null },
                        { id: 'lead_magnet_ideas', label: 'Lead Magnet Ideas', icon: <Lightbulb size={12} /> },
                        { id: 'whatsapp_template', label: 'WhatsApp Template', icon: <MessageCircle size={12} /> },
                        { id: 'facebook_post', label: 'Facebook Post', icon: <Facebook size={12} /> },
                        { id: 'pov_video_script', label: 'POV Video Script', icon: <Video size={12} /> }
                    ].map(t => (
                        <button
                            key={t.id}
                            onClick={() => { setCopyType(t.id as any); setResult(null); setHasSavedManually(false); }}
                            className={`py-2 px-3 text-xs rounded-lg border capitalize transition-colors flex items-center justify-center gap-1 text-center ${
                                copyType === t.id 
                                ? 'bg-blue-600 text-white border-blue-600' 
                                : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700'
                            }`}
                        >
                            {t.icon}
                            {t.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700 dark:text-gray-300 flex items-center">
                    Template / Scenario
                    <Tooltip content="Choose a framework (like 'FOMO' or 'Storytelling') to guide the style of the copy." />
                </label>
                <div className="relative">
                    <select
                        value={selectedTemplate}
                        onChange={(e) => setSelectedTemplate(e.target.value)}
                        className="w-full p-3 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg appearance-none focus:ring-2 focus:ring-blue-500 outline-none text-sm dark:text-white"
                    >
                        {TEMPLATES.map(t => (
                            <option key={t.id} value={t.id}>{t.label}</option>
                        ))}
                    </select>
                    <div className="absolute inset-y-0 right-0 flex items-center px-3 pointer-events-none text-gray-500">
                        <FileText size={16} />
                    </div>
                </div>
            </div>

            <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700 dark:text-gray-300 flex items-center">
                    Product / Topic
                    <Tooltip content="The main subject of your copy. Can be a product name, a specific pain point, or an idea." />
                </label>
                <div className="relative">
                    <input 
                        type="text" 
                        value={topic}
                        onChange={(e) => setTopic(e.target.value)}
                        placeholder="e.g. Keto diet plan, AI marketing tools"
                        className="w-full p-3 pr-10 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-900 placeholder-gray-500 dark:bg-gray-800 dark:text-white dark:placeholder-gray-400" 
                    />
                    <div className="absolute right-2 top-1/2 -translate-y-1/2">
                       <VoiceInput onTranscript={handleVoiceInput} />
                    </div>
                </div>
            </div>

            <button 
                onClick={handleCopyGen}
                disabled={!topic || loading}
                className="w-full bg-blue-600 text-white py-3 rounded-xl font-semibold hover:bg-blue-700 disabled:opacity-50 flex justify-center items-center gap-2 shadow-lg shadow-blue-200 dark:shadow-blue-900/20"
            >
                {loading ? <Loader2 className="animate-spin" size={18} /> : (isPreviewMode ? 'Generate Preview' : 'Generate Content')}
            </button>
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in">
             <div className="bg-purple-50 dark:bg-purple-900/30 border border-purple-200 dark:border-purple-700 text-purple-800 dark:text-purple-200 px-3 py-2 rounded-lg text-xs flex items-center gap-2">
                <ImageIcon size={12} className="text-purple-600 dark:text-purple-400" />
                Upload competitor screenshots to reveal their strategy.
             </div>

            {/* Upload Area */}
            <div className={`border-2 border-dashed rounded-xl p-6 flex flex-col items-center justify-center transition-all relative overflow-hidden ${
                uploading 
                ? 'border-blue-400 bg-blue-50 dark:bg-blue-900/10' 
                : error && !selectedImage
                    ? 'border-red-300 bg-red-50 dark:border-red-800 dark:bg-red-900/10'
                    : 'border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer'
            }`}>
                <input 
                    type="file" 
                    accept="image/*"
                    onChange={handleImageUpload}
                    disabled={uploading || loading}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed"
                />

                {uploading ? (
                    <div className="flex flex-col items-center animate-pulse">
                        <Loader2 className="text-blue-500 mb-2 animate-spin" size={32} />
                        <p className="text-sm text-blue-600 font-medium">Processing image...</p>
                    </div>
                ) : (
                    <>
                        <UploadCloud className={`${error && !selectedImage ? 'text-red-400' : 'text-gray-400'} mb-2`} size={32} />
                        <p className={`text-sm font-medium ${error && !selectedImage ? 'text-red-500' : 'text-gray-500'}`}>
                            {error && !selectedImage ? 'Tap to retry' : 'Tap to upload image'}
                        </p>
                        <p className="text-[10px] text-gray-400 mt-1">Max size 4MB • JPG, PNG, WebP</p>
                    </>
                )}
            </div>

            {selectedImage && !uploading && !error && (
                <div className="relative rounded-lg overflow-hidden border border-gray-200 dark:border-gray-700 group">
                    <img src={`data:${mimeType};base64,${selectedImage}`} alt="Preview" className="w-full h-48 object-cover" />
                    <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                        <p className="text-white text-xs font-medium bg-black/50 px-3 py-1 rounded-full backdrop-blur-sm flex items-center gap-1">
                            <RefreshCw size={10} /> Change Image
                        </p>
                    </div>
                </div>
            )}

            {/* Visual Progress Indicator for Analysis */}
            {loading && (
                 <div className="space-y-2 animate-in fade-in">
                    <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400 px-1">
                        <span className="font-medium text-purple-600 dark:text-purple-400">Analyzing visual elements...</span>
                        <span>{Math.round(analysisProgress)}%</span>
                    </div>
                    <div className="h-2 w-full bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                        <div 
                            className="h-full bg-gradient-to-r from-blue-500 to-purple-600 rounded-full transition-all duration-300 ease-out" 
                            style={{ width: `${analysisProgress}%` }}
                        />
                    </div>
                 </div>
            )}

            <button 
                onClick={handleAnalyze}
                disabled={!selectedImage || loading || uploading}
                className="w-full bg-purple-600 text-white py-3 rounded-xl font-semibold hover:bg-purple-700 disabled:opacity-50 flex justify-center items-center gap-2 shadow-lg shadow-purple-200 dark:shadow-purple-900/20 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        Analyzing Strategy...
                    </>
                ) : (
                    <>
                        <Sparkles size={18} />
                        Analyze Strategy
                    </>
                )}
            </button>
          </div>
        )}

        {/* Error Display */}
        {error && (
            <div className="mt-6 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-300 flex items-start gap-3 animate-in fade-in slide-in-from-bottom-2">
                <AlertTriangle size={20} className="shrink-0 mt-0.5" />
                <div>
                    <h3 className="font-semibold text-sm">Action Failed</h3>
                    <p className="text-xs mt-1 leading-relaxed">{error}</p>
                </div>
            </div>
        )}

        {/* Results / Preview Area */}
        {result && (
            <div className="mt-6 p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-semibold text-gray-800 dark:text-gray-200">
                        {isPreviewMode ? 'Preview' : 'Result'}
                    </h3>
                    <div className="flex gap-2 items-center">
                        {isPreviewMode ? (
                           <button
                             onClick={handleManualSave}
                             disabled={hasSavedManually}
                             className={`text-xs font-medium px-3 py-1.5 rounded-lg flex items-center gap-1.5 transition-all ${
                                hasSavedManually 
                                ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 cursor-default'
                                : 'bg-blue-600 text-white hover:bg-blue-700 shadow-sm'
                             }`}
                           >
                              {hasSavedManually ? (
                                <>
                                  <CheckCircle2 size={12} /> Saved
                                </>
                              ) : (
                                <>
                                  <Save size={12} /> Save Project
                                </>
                              )}
                           </button>
                        ) : (
                            <span className="text-gray-400 text-xs flex items-center gap-1">
                                <CheckCircle2 size={12} className="text-green-500" /> Saved
                            </span>
                        )}

                        <div className="h-4 w-px bg-gray-200 dark:bg-gray-700 mx-1"></div>

                        <button 
                            onClick={() => {
                                navigator.clipboard.writeText(result);
                                // Optional: You could add a tiny "Copied!" feedback here
                            }}
                            className="text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 flex items-center gap-1 text-xs px-2 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                        >
                            <Copy size={16} /> Copy
                        </button>
                    </div>
                </div>

                <div className="prose prose-sm prose-blue max-w-none text-gray-600 dark:text-gray-300 dark:prose-invert">
                    <ReactMarkdown
                        components={activeTab === 'analyze' ? {
                            // Custom renderer for Analysis Tab results
                            h2: ({node, ...props}) => (
                                <div className="mt-6 mb-2">
                                    <span className="bg-purple-100 dark:bg-purple-900/50 text-purple-800 dark:text-purple-300 text-xs font-bold px-2 py-1 rounded uppercase tracking-wider">
                                        {props.children}
                                    </span>
                                </div>
                            ),
                            ul: ({node, ...props}) => <ul className="space-y-2 mt-2" {...props} />,
                            li: ({node, ...props}) => (
                                <li className="flex items-start gap-2 bg-gray-50 dark:bg-gray-700/50 p-2 rounded-lg text-sm">
                                    <CheckCircle2 size={14} className="text-green-500 shrink-0 mt-0.5" />
                                    <span>{props.children}</span>
                                </li>
                            ),
                            p: ({node, ...props}) => <p className="mb-2 text-sm leading-relaxed" {...props} />
                        } : undefined} // Default rendering for copy tab
                    >
                        {result}
                    </ReactMarkdown>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default QuickTools;

import React, { useState, useEffect } from 'react';
import { Home, Wand2, MessageSquare, Zap, Settings, MoreVertical, Moon, Sun, HardDrive, User, LogOut, Cloud, Check } from 'lucide-react';
import { AppView, UserProfile } from '../types';
import { StorageModal } from './StorageModal';

interface LayoutProps {
  children: React.ReactNode;
  currentView: AppView;
  onNavigate: (view: AppView) => void;
  user: UserProfile;
  onLogout: () => void;
}

const Layout: React.FC<LayoutProps> = ({ children, currentView, onNavigate, user, onLogout }) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showStorage, setShowStorage] = useState(false);
  const [isSynced, setIsSynced] = useState(true);

  // Swipe State
  const [touchStart, setTouchStart] = useState<{x: number, y: number} | null>(null);
  const [touchEnd, setTouchEnd] = useState<{x: number, y: number} | null>(null);

  // Simulate Cloud Sync Pulse
  useEffect(() => {
    const interval = setInterval(() => {
        setIsSynced(false);
        setTimeout(() => setIsSynced(true), 2000);
    }, 30000);
    return () => clearInterval(interval);
  }, []);

  const navItems = [
    { id: AppView.DASHBOARD, label: 'Home', icon: Home },
    { id: AppView.WIZARD, label: 'Builder', icon: Wand2 },
    { id: AppView.TOOLS, label: 'Tools', icon: Zap },
    { id: AppView.CHAT, label: 'Coach', icon: MessageSquare },
  ];

  const toggleTheme = (mode: 'light' | 'dark' | 'system') => {
      if (mode === 'dark') {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else if (mode === 'light') {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      } else {
          localStorage.removeItem('theme');
          if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
              document.documentElement.classList.add('dark');
          } else {
              document.documentElement.classList.remove('dark');
          }
      }
      setShowMenu(false);
  };

  // Initialize theme on mount
  React.useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // --- Swipe Handlers ---
  const minSwipeDistance = 50;

  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart({
        x: e.targetTouches[0].clientX,
        y: e.targetTouches[0].clientY
    });
  }

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd({
        x: e.targetTouches[0].clientX,
        y: e.targetTouches[0].clientY
    });
  }

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;

    const xDistance = touchStart.x - touchEnd.x;
    const yDistance = touchStart.y - touchEnd.y;

    if (Math.abs(xDistance) > minSwipeDistance && Math.abs(xDistance) > Math.abs(yDistance)) {
        const isLeftSwipe = xDistance > 0;
        const isRightSwipe = xDistance < 0;

        const currentIndex = navItems.findIndex(item => item.id === currentView);
        let nextIndex = currentIndex;

        if (isLeftSwipe && currentIndex < navItems.length - 1) {
            // Swipe Left -> Go Next
            nextIndex = currentIndex + 1;
        } 

        if (isRightSwipe && currentIndex > 0) {
            // Swipe Right -> Go Previous
            nextIndex = currentIndex - 1;
        }

        if (nextIndex !== currentIndex) {
            onNavigate(navItems[nextIndex].id);
        }
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex justify-center transition-colors duration-200">
      {/* Mobile container simulation */}
      <div 
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        className="w-full max-w-md bg-white dark:bg-gray-800 h-[100dvh] flex flex-col shadow-2xl relative overflow-hidden transition-colors duration-200 touch-pan-y"
      >

        {/* Header */}
        <header className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white p-4 shadow-md z-20 flex items-center justify-between shrink-0 relative">
          <div className="flex items-center gap-2">
             <div className="bg-white/20 p-1.5 rounded-lg">
                <Wand2 size={18} className="text-white" />
             </div>
             <h1 className="text-lg font-bold tracking-tight">FunnelMate AI</h1>
          </div>

          <div className="flex items-center gap-3">
              {/* Cloud Sync Indicator */}
              <div className="flex items-center gap-1.5 bg-black/20 px-2 py-1 rounded-full border border-white/5 backdrop-blur-sm">
                 <Cloud size={10} className="text-blue-200" />
                 <span className="text-[10px] font-medium text-blue-100 flex items-center gap-1">
                    {isSynced ? 'Saved' : 'Syncing...'}
                    {isSynced && <Check size={8} className="text-green-400" />}
                 </span>
              </div>

              <button onClick={() => setShowMenu(!showMenu)} className="p-1 hover:bg-white/10 rounded-full transition-colors relative">
                  <MoreVertical size={20} className="text-white" />
              </button>
          </div>

          {/* Unified Settings Dropdown */}
          {showMenu && (
              <div className="absolute top-14 right-4 bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-100 dark:border-gray-700 w-64 z-50 animate-in fade-in slide-in-from-top-2 overflow-hidden">

                  {/* Profile Section */}
                  <div className="p-4 bg-gray-50 dark:bg-gray-900/50 border-b border-gray-100 dark:border-gray-700 flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900 overflow-hidden border border-gray-200 dark:border-gray-700 shrink-0">
                           <img src={user.avatar} alt="Profile" className="w-full h-full object-cover" />
                      </div>
                      <div className="flex-1 min-w-0">
                          <p className="text-sm font-bold text-gray-900 dark:text-gray-100 truncate">{user.name}</p>
                          <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{user.email}</p>
                          {user.plan === 'pro' && (
                             <span className="inline-block mt-1 text-[10px] bg-indigo-100 dark:bg-indigo-900 text-indigo-700 dark:text-indigo-300 px-1.5 py-0.5 rounded font-bold">PRO PLAN</span>
                          )}
                      </div>
                  </div>

                  {/* Menu Items */}
                  <div className="p-2 space-y-1">
                      {/* Data Section */}
                      <div className="px-3 py-2 mt-1 text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider">Data</div>
                      <button 
                        onClick={() => { setShowStorage(true); setShowMenu(false); }} 
                        className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2.5 text-gray-700 dark:text-gray-200 transition-colors"
                      >
                          <HardDrive size={16} className="text-gray-500 dark:text-gray-400" /> 
                          <span>Local Backup</span>
                      </button>

                      <div className="my-1 border-t border-gray-100 dark:border-gray-700" />

                      {/* Appearance Section */}
                      <div className="px-3 py-2 text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider">Appearance</div>
                      <button onClick={() => toggleTheme('light')} className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2.5 text-gray-700 dark:text-gray-200 transition-colors">
                          <Sun size={16} className="text-gray-500 dark:text-gray-400" /> 
                          <span>Light Mode</span>
                      </button>
                      <button onClick={() => toggleTheme('dark')} className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2.5 text-gray-700 dark:text-gray-200 transition-colors">
                          <Moon size={16} className="text-gray-500 dark:text-gray-400" /> 
                          <span>Dark Mode</span>
                      </button>
                      <button onClick={() => toggleTheme('system')} className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2.5 text-gray-700 dark:text-gray-200 transition-colors">
                          <Settings size={16} className="text-gray-500 dark:text-gray-400" /> 
                          <span>System Default</span>
                      </button>

                      <div className="my-1 border-t border-gray-100 dark:border-gray-700" />

                      {/* Log Out */}
                      <button onClick={() => { onLogout(); setShowMenu(false); }} className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-2.5 text-red-600 dark:text-red-400 transition-colors">
                          <LogOut size={16} /> 
                          <span>Sign Out</span>
                      </button>
                  </div>
              </div>
          )}

          {/* Click outside to close */}
          {showMenu && (
              <div 
                  className="fixed inset-0 z-40 bg-transparent" 
                  onClick={() => setShowMenu(false)}
              />
          )}
        </header>

        {/* Storage Modal */}
        <StorageModal isOpen={showStorage} onClose={() => setShowStorage(false)} />

        {/* Main Content (Scrollable) */}
        <main 
            className="flex-1 overflow-y-auto no-scrollbar relative bg-slate-50 dark:bg-gray-900 z-10 transition-colors duration-200"
        >
          {children}
        </main>

        {/* Bottom Navigation */}
        <nav className="bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700 px-2 py-2 pb-5 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-30 shrink-0 transition-colors duration-200">
          <div className="flex justify-between items-center">
            {navItems.map((item) => {
              const isActive = currentView === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => onNavigate(item.id)}
                  className="relative group flex flex-col items-center justify-center flex-1 h-14"
                >
                  {/* Active Indicator Background */}
                  {isActive && (
                    <span className="absolute -top-2 w-8 h-1 bg-blue-600 rounded-b-lg shadow-[0_0_8px_rgba(37,99,235,0.5)] transition-all duration-300" />
                  )}

                  <div className={`transition-all duration-200 ${isActive ? '-translate-y-1' : 'group-hover:-translate-y-0.5'}`}>
                    <item.icon 
                      size={24} 
                      className={`mb-1 transition-colors duration-200 ${
                        isActive ? 'text-blue-600 dark:text-blue-400 fill-blue-50 dark:fill-blue-900/20' : 'text-gray-400 dark:text-gray-500 group-hover:text-gray-600 dark:group-hover:text-gray-300'
                      }`} 
                      strokeWidth={isActive ? 2.5 : 2}
                    />
                  </div>

                  <span className={`text-[10px] font-medium transition-colors duration-200 ${
                    isActive ? 'text-blue-600 dark:text-blue-400' : 'text-gray-400 dark:text-gray-500 group-hover:text-gray-600 dark:group-hover:text-gray-300'
                  }`}>
                    {item.label}
                  </span>
                </button>
              );
            })}
          </div>
        </nav>

      </div>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import FunnelWizard from './components/FunnelWizard';
import ChatCoach from './components/ChatCoach';
import QuickTools from './components/QuickTools';
import AuthScreen from './components/AuthScreen';
import { AppView, FunnelProject, UserProfile } from './types';
import { Plus, History, Mail, Download, FileText, Image as ImageIcon, MessageCircle, MessageSquare, ArrowRight } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('funnel_user');
        return saved ? JSON.parse(saved) : null;
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [activeProject, setActiveProject] = useState<FunnelProject | null>(null);

  // Navigation State for Animations
  const [slideDirection, setSlideDirection] = useState<'forward' | 'backward' | 'none'>('none');
  const viewOrder = [AppView.DASHBOARD, AppView.WIZARD, AppView.TOOLS, AppView.CHAT];

  // Initialize projects from localStorage if available
  const [projects, setProjects] = useState<FunnelProject[]>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('funnel_projects');
      if (saved) {
        try {
          return JSON.parse(saved);
        } catch (e) {
          console.error('Failed to parse projects from local storage');
        }
      }
    }
    return [];
  });

  const [toolParams, setToolParams] = useState<{ topic: string, type: any } | null>(null);

  // Persist projects
  useEffect(() => {
    localStorage.setItem('funnel_projects', JSON.stringify(projects));
  }, [projects]);

  // Persist User
  useEffect(() => {
      if (currentUser) {
          localStorage.setItem('funnel_user', JSON.stringify(currentUser));
      } else {
          localStorage.removeItem('funnel_user');
      }
  }, [currentUser]);

  const handleLogin = (user: UserProfile) => {
      setCurrentUser(user);
      setCurrentView(AppView.DASHBOARD);
  };

  const handleLogout = () => {
      setCurrentUser(null);
  };

  const handleNavigation = (view: AppView) => {
    if (view === currentView) return;

    const prevIndex = viewOrder.indexOf(currentView);
    const nextIndex = viewOrder.indexOf(view);

    if (nextIndex > prevIndex) setSlideDirection('forward');
    else if (nextIndex < prevIndex) setSlideDirection('backward');
    else setSlideDirection('none');

    setCurrentView(view);
    if (view !== AppView.CHAT) setActiveProject(null);
  };

  // "Auto-Save" Server Simulation
  const handleAutoSave = (project: FunnelProject) => {
    setProjects(prev => {
        const exists = prev.findIndex(p => p.id === project.id);
        if (exists >= 0) {
            const updated = [...prev];
            updated[exists] = project;
            return updated;
        } else {
            return [project, ...prev];
        }
    });
  };

  const handleOpenProject = (project: FunnelProject) => {
      setActiveProject(project);
      if (project.type === 'CHAT_SESSION') {
          handleNavigation(AppView.CHAT);
      } else if (project.type === 'STRATEGY') {
          handleDownloadPDF(project);
      } else {
          alert("Content copied to clipboard!");
          navigator.clipboard.writeText(project.content);
      }
  };

  const handleGenerateEmails = (project: FunnelProject) => {
    setToolParams({
        topic: `${project.productName} (Target Audience: ${project.targetAudience})`,
        type: 'email_sequence'
    });
    handleNavigation(AppView.TOOLS);
  };

  const handleToolRequest = (type: any, topic: string) => {
    setToolParams({
        topic: topic,
        type: type
    });
    handleNavigation(AppView.TOOLS);
  };

  const handleDownloadPDF = (project: FunnelProject) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const htmlContent = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>${project.name} - FunnelMate Strategy</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <script src="https://cdn.jsdelivr.net/npm/marked/marked.min.js"></script>
        <style>
            @page { margin: 0; size: auto; }
            body { background: #f9fafb; -webkit-print-color-adjust: exact; print-color-adjust: exact; font-family: sans-serif; padding: 3rem; color: #334155; }
            h1 { font-size: 2rem; font-weight: 800; margin-bottom: 0.5rem; color: #0f172a; text-align: center; }
            .subtitle { text-align: center; color: #64748b; margin-bottom: 3rem; font-size: 0.875rem; }

            /* Overview Section */
            .overview-box { background: #eef2ff; border: 1px solid #c7d2fe; border-radius: 1rem; padding: 1.5rem; margin-bottom: 3rem; color: #3730a3; page-break-inside: avoid; }
            .overview-box strong { color: #312e81; font-weight: 800; }

            /* Step Cards */
            .step-card { background: white; border: 1px solid #e2e8f0; border-radius: 1rem; padding: 2rem; margin-bottom: 2rem; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); page-break-inside: avoid; }

            /* Step Pill */
            h2 { 
                background: #dbeafe; 
                color: #1e40af; 
                display: inline-block; 
                padding: 0.25rem 0.75rem; 
                border-radius: 0.5rem; 
                font-size: 0.75rem; 
                font-weight: 800; 
                text-transform: uppercase; 
                letter-spacing: 0.05em;
                margin-bottom: 1rem; 
            }

            /* Step Title */
            h3 { font-size: 1.25rem; font-weight: 700; color: #0f172a; margin-bottom: 0.75rem; margin-top: 0; }

            /* Script Block */
            blockquote { 
                background: #f8fafc; 
                padding: 1.5rem; 
                border-radius: 0.75rem; 
                font-style: italic; 
                color: #475569; 
                border-left: 4px solid #cbd5e1; 
                margin: 1.5rem 0; 
                font-family: serif;
            }

            /* Checklist */
            ul { list-style: none; padding: 0; margin: 1.5rem 0; }
            ul li { 
                padding-left: 2rem; 
                position: relative; 
                margin-bottom: 0.75rem; 
                color: #475569; 
                font-size: 0.875rem; 
                font-weight: 500;
            }
            ul li::before { 
                content: '✓'; 
                color: #10b981; 
                background: #d1fae5;
                width: 1.25rem;
                height: 1.25rem;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                position: absolute; 
                left: 0; 
                font-size: 0.75rem;
                font-weight: bold;
                top: 0;
            }

            /* CTA */
            .cta-text { 
                text-align: center; 
                margin-top: 2rem; 
                padding-top: 1.5rem;
                border-top: 1px solid #f1f5f9;
                color: #2563eb; 
                font-weight: 700; 
                font-size: 0.875rem;
                text-transform: uppercase;
                letter-spacing: 0.05em;
            }

            p { margin: 0.5rem 0; line-height: 1.6; }
        </style>
      </head>
      <body>
        <div class="max-w-4xl mx-auto">
            <div class="header">
                <h1>${project.name}</h1>
                <p class="subtitle">Generated by FunnelMate AI • ${new Date(project.createdAt).toLocaleDateString()}</p>
            </div>
            <div id="content"></div>
        </div>
        <script>
           const markdownText = \`${project.content.replace(/`/g, '\\`').replace(/\$/g, '\\$')}\`;
           const html = marked.parse(markdownText);
           const contentDiv = document.getElementById('content');
           contentDiv.innerHTML = html;

           // Post-process to group content into cards
           const children = Array.from(contentDiv.children);
           contentDiv.innerHTML = '';

           let currentWrapper = null;

           children.forEach(child => {
               if (child.tagName === 'H1') {
                   currentWrapper = document.createElement('div');
                   currentWrapper.className = 'overview-box';
                   child.style.display = 'none';
                   contentDiv.appendChild(currentWrapper);
               } else if (child.tagName === 'H2') {
                   currentWrapper = document.createElement('div');
                   currentWrapper.className = 'step-card';
                   contentDiv.appendChild(currentWrapper);
                   currentWrapper.appendChild(child);
               } else if (child.tagName === 'STRONG' && child.textContent.toLowerCase().includes('call to action')) {
                   child.className = 'cta-text';
                   child.style.display = 'block';
                   if (currentWrapper) currentWrapper.appendChild(child);
               } else {
                   if (currentWrapper) {
                       currentWrapper.appendChild(child);
                   } else {
                       contentDiv.appendChild(child);
                   }
               }
           });

           setTimeout(() => { window.print(); }, 800);
        </script>
      </body>
      </html>
    `;
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  const getAnimationClass = () => {
      if (slideDirection === 'forward') return 'animate-slide-right';
      if (slideDirection === 'backward') return 'animate-slide-left';
      return 'animate-fade';
  };

  const renderDashboard = () => (
    <div className="p-4 space-y-6">

      {/* 1. Welcome / CTA */}
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl p-6 text-white shadow-lg shadow-blue-200 dark:shadow-blue-900/20">
        <h2 className="text-2xl font-bold mb-2">Welcome Back, {currentUser?.name}!</h2>
        <p className="opacity-90 text-sm mb-4">Ready to build your next income stream?</p>
        <button
          onClick={() => { setActiveProject(null); handleNavigation(AppView.WIZARD); }}
          className="bg-white text-blue-700 px-4 py-2 rounded-lg font-semibold text-sm flex items-center gap-2 hover:bg-blue-50 transition-colors shadow-sm"
        >
          <Plus size={16} /> New Funnel
        </button>
      </div>

      {/* 3. History Section */}
      <div>
        <h3 className="text-lg font-bold text-gray-800 dark:text-gray-100 mb-3 flex items-center gap-2">
            <History size={18} className="text-gray-500 dark:text-gray-400" /> Recent History
        </h3>
        {projects.length === 0 ? (
          <div className="text-center py-10 bg-white dark:bg-gray-800 rounded-xl border border-dashed border-gray-300 dark:border-gray-700">
            <p className="text-gray-400 dark:text-gray-500 text-sm">No funnels yet.</p>
            <p className="text-gray-400 dark:text-gray-500 text-xs mt-1">Start the Wizard to create one!</p>
          </div>
        ) : (
          <div className="space-y-3 pb-20">
            {projects.map(p => (
              <div key={p.id} className="bg-white dark:bg-gray-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow group">
                <div 
                    onClick={() => handleOpenProject(p)}
                    className="flex justify-between items-start cursor-pointer"
                >
                    <div className="flex items-start gap-3">
                        <div className={`p-2 rounded-lg shrink-0 ${
                            p.type === 'STRATEGY' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' : 
                            p.type === 'ANALYSIS' ? 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400' : 
                            p.type === 'CAMPAIGN_WA' ? 'bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400' :
                            p.type === 'CAMPAIGN_EMAIL' ? 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400' :
                            p.type === 'CHAT_SESSION' ? 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400' :
                            'bg-yellow-100 text-yellow-600 dark:bg-yellow-900/30 dark:text-yellow-400'
                        }`}>
                            {p.type === 'STRATEGY' && <FileText size={20} />}
                            {p.type === 'ANALYSIS' && <ImageIcon size={20} />}
                            {(p.type === 'COPY' || p.type === 'CAMPAIGN_EMAIL') && <Mail size={20} />}
                            {p.type === 'CAMPAIGN_WA' && <MessageCircle size={20} />}
                            {p.type === 'CHAT_SESSION' && <MessageSquare size={20} />}
                        </div>
                        <div>
                            <h4 className="font-semibold text-gray-800 dark:text-gray-200 line-clamp-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{p.name}</h4>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1 capitalize">
                                {p.type === 'CAMPAIGN_WA' ? 'WhatsApp Campaign' : p.type === 'CHAT_SESSION' ? 'Chat Coach Session' : p.type.toLowerCase().replace('_', ' ')} • {new Date(p.createdAt).toLocaleDateString()}
                            </p>
                        </div>
                    </div>
                </div>

                <div className="mt-4 flex gap-2">
                    {p.type === 'STRATEGY' && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); handleGenerateEmails(p); }}
                            className="flex-1 text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 py-2 rounded-lg text-xs font-medium flex items-center justify-center gap-1 hover:bg-blue-100 dark:hover:bg-blue-900/30"
                        >
                            <Mail size={12} /> Email Sequence
                        </button>
                    )}
                    {(p.type === 'STRATEGY' || p.type === 'COPY' || p.type === 'CAMPAIGN_EMAIL') && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); handleDownloadPDF(p); }}
                            className="flex-1 text-gray-600 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 py-2 rounded-lg text-xs font-medium flex items-center justify-center gap-1 hover:bg-gray-200 dark:hover:bg-gray-600"
                        >
                            <Download size={12} /> Download
                        </button>
                    )}
                     {p.type === 'CHAT_SESSION' && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); handleOpenProject(p); }}
                            className="flex-1 text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-900/20 py-2 rounded-lg text-xs font-medium flex items-center justify-center gap-1 hover:bg-indigo-100 dark:hover:bg-indigo-900/30"
                        >
                            <ArrowRight size={12} /> Resume Chat
                        </button>
                    )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );

  // AUTH GUARD
  if (!currentUser) {
      return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <Layout 
        currentView={currentView} 
        onNavigate={handleNavigation}
        user={currentUser}
        onLogout={handleLogout}
    >
      <div key={currentView} className={`h-full ${getAnimationClass()}`}>
        {currentView === AppView.DASHBOARD && renderDashboard()}
        {currentView === AppView.WIZARD && (
            <FunnelWizard 
                onAutoSave={handleAutoSave} 
                onToolRequest={handleToolRequest} 
                onDownload={handleDownloadPDF} 
                initialData={activeProject?.type === 'STRATEGY' ? activeProject : undefined} 
            />
        )}
        {currentView === AppView.CHAT && (
            <ChatCoach 
                onAutoSave={handleAutoSave} 
                initialProject={activeProject?.type === 'CHAT_SESSION' ? activeProject : undefined} 
            />
        )}
        {currentView === AppView.TOOLS && (
            <QuickTools 
                initialTopic={toolParams?.topic} 
                initialType={toolParams?.type} 
                onAutoSave={handleAutoSave}
            />
        )}
      </div>
    </Layout>
  );
};

export default App;
